<template><v-expansion-panels flat accordion class="mt-3"><v-expansion-panel><v-expansion-panel-header>{{ $u1t('Голосовое управление Alexa') }}</v-expansion-panel-header><v-expansion-panel-content><p>{{ $u1t('Личный навык Amazon и внешняя HTTPS-ссылка.') }}</p><v-alert v-if="error" dense type="warning">{{ error }}</v-alert><v-text-field v-model="skillId" label="Alexa Skill ID" outlined dense /><v-text-field v-model="endpoint" label="HTTPS URL · /u1-alexa/skill" outlined dense /><v-btn outlined :disabled="busy || !skillId || !validEndpoint" @click="setup">{{ $u1t('Подготовить подключение') }}</v-btn><v-btn v-if="setupConfig" outlined class="mt-2" @click="downloadConfig">{{ $u1t('Скачать настройки навыка') }}</v-btn><p v-if="setupConfig" class="mt-2">{{ $u1t('Секретный ключ. Не публикуйте этот файл.') }}</p><v-switch :input-value="state?.enabled" :disabled="busy || !state?.skillId" :label="$u1t('Включить голосовое управление')" @change="enable" /><v-btn outlined :disabled="busy || !state?.enabled || state?.linked" @click="pair">{{ $u1t('Получить код привязки') }}</v-btn><p v-if="code" class="mt-3"><strong style="font-size:24px;letter-spacing:4px">{{ code }}</strong> · 5 min</p><p v-if="state?.linked">{{ $u1t('Аккаунт Alexa привязан') }}</p><p><a href="https://github.com/manwhocode/u1-companion/releases/download/v0.1.1-alpha.15/U1-Alexa-Skill.zip" target="_blank" rel="noopener noreferrer">{{ $u1t('Скачать навык Alexa') }}</a> · <a href="https://github.com/manwhocode/u1-companion/blob/main/alexa-skill/README.ru.md" target="_blank" rel="noopener noreferrer">{{ $u1t('Инструкция') }}</a></p><p>DE: Alexa, öffne Druck Helfer. EN: Alexa, open Printer Helper.</p><p>{{ $u1t('Команды запуска и движения требуют подтверждения.') }}</p></v-expansion-panel-content></v-expansion-panel></v-expansion-panels></template>
<script lang="ts">
import Vue from 'vue'
import { Component } from 'vue-property-decorator'
import { u1DataRequest } from '@/utils/u1DataClient'
interface State {enabled:boolean;skillId:string;linked:boolean;bridgeKey?:string;endpoint?:string}
@Component
export default class U1VoiceControl extends Vue {
  pairTimer: ReturnType<typeof setInterval> | null = null
  beforeDestroy () { if (this.pairTimer) clearInterval(this.pairTimer) }
  async checkPair () { try { this.state = await u1DataRequest<State>('voice_state'); if (this.state.linked && this.pairTimer) { clearInterval(this.pairTimer); this.pairTimer = null; this.code = '' } } catch { /* Next poll retries without touching any printer state. */ } }
  state: State | null = null; skillId = ''; endpoint = ''; code = ''; error = ''; busy = false; setupConfig: {skillId:string;url:string;key:string} | null = null
  get validEndpoint () { try { const u = new URL(this.endpoint); return u.protocol === 'https:' && u.pathname === '/u1-alexa/skill' && !u.username && !u.password && !u.search && !u.hash } catch { return false } }
  mounted () { void this.load() }
  async load () { try { this.state = await u1DataRequest<State>('voice_state'); this.skillId = this.state.skillId; this.endpoint = this.state.endpoint || this.endpoint } catch (e) { this.error = String(e) } }
  async setup () { this.busy = true; this.error = ''; try { this.state = await u1DataRequest<State>('voice_setup', {skillId:this.skillId}); this.setupConfig = {skillId:this.skillId,url:this.endpoint,key:this.state.bridgeKey!}; this.code = '' } catch (e) { this.error = String(e) } finally { this.busy = false } }
  async enable (enabled:boolean) { this.busy = true; try { this.state = await u1DataRequest<State>('voice_enable', {enabled}); this.error = '' } catch (e) { this.error = String(e) } finally { this.busy = false } }
  async pair () { this.busy = true; try { this.code = (await u1DataRequest<{code:string}>('voice_pair')).code; this.error = ''; if (this.pairTimer) clearInterval(this.pairTimer); this.pairTimer = setInterval(() => { void this.checkPair() }, 3000); setTimeout(() => { if (this.pairTimer) { clearInterval(this.pairTimer); this.pairTimer = null } }, 300000) } catch (e) { this.error = String(e) } finally { this.busy = false } }
  downloadConfig () { if (!this.setupConfig) return; const url = URL.createObjectURL(new Blob([JSON.stringify(this.setupConfig,null,2)], {type:'application/json'})); const a = document.createElement('a'); a.href = url; a.download = 'config.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url),1000) }
}
</script>
